from collections import Counter

import pytesseract
from PIL import Image, ImageOps, ImageFilter
import openpyxl

IMG_DIR = '/app/workspace/dataset/img'
OUT = '/app/workspace/stat_ocr.xlsx'

TIERS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE',
     'NETT TOTAL', 'NET TOTAL', 'ROUNDED TOTAL', 'TOTAL ROUNDED',
     'TOTAL AFTER ROUNDING', 'TOTAL INCL GST', 'TOTAL RM INCLUDING GST'],
]
EXCLUSIONS = [
    'SUBTOTAL', 'SUB TOTAL', 'SUB-TOTAL',
    'TAX', 'GST', 'SST',
    'DISCOUNT', 'CHANGE', 'CASH TENDERED', 'CASH RECEIVED', 'CASH PAYMENT',
    'VISA', 'MASTERCARD', 'DEBIT', 'CREDIT', 'CARD', 'PAYMENT',
    'ROUNDING ADJ', 'ROUNDING ADJUSTMENT',
    'TOTAL GST', 'TOTAL TAX', 'TOTAL SST', 'GST TOTAL', 'TAX TOTAL',
    'TOTAL ITEMS', 'TOTAL ITEM(S)', 'ITEM COUNT', 'TOTAL QTY', 'TOTAL QUANTITY',
    'TOTAL SAVINGS', 'EXCLUDING', 'EXCL GST', 'AMT EXCL',
    'DESCRIPTION', 'QTY PRICE AMOUNT', 'PRICE AMOUNT', 'AVERAGE', 'PAX',
]
SECTION_CUTOFFS = ['GST SUMMARY', 'TAX SUMMARY', 'TAX CODE']

AMOUNT_RE = re.compile(r'(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.\d])')


def to_float(tok):
    return float(tok.replace(',', ''))


def normalize_token(tok):
    # Correct common OCR confusions in numeric tokens
    repl = {'O': '0', 'o': '0', 'Q': '0', 'l': '1', 'I': '1', '|': '1',
            'S': '5', 'B': '8', 'u': '0'}
    out = []
    for c in tok:
        out.append(repl.get(c, c))
    return ''.join(out)


def normalize_line(line):
    # Replace standalone RN with RM
    line = re.sub(r'\bRN\b', 'RM', line)
    # Collapse NN NN at end of a keyword line into NN.NN
    line = re.sub(r'(\d{1,3})\s+(\d{2})\s*$', r'\1.\2', line)
    # Replace colon with dot inside amount-looking tokens
    line = re.sub(r'(\d)[:](\d{2})\b', r'\1.\2', line)
    return line


def variants(path):
    img = Image.open(path)
    gray = ImageOps.autocontrast(img.convert('L'))
    w, h = gray.size
    up2 = gray.resize((w * 2, h * 2), Image.LANCZOS)
    up3 = gray.resize((w * 3, h * 3), Image.LANCZOS)
    binz = gray.point(lambda p: 255 if p > 150 else 0)
    return [
        (img, '--psm 6'),
        (gray, '--psm 6'),
        (up2, '--psm 6'),
        (up3, '--psm 4'),
        (gray, '--psm 11'),
        (binz, '--psm 6'),
    ]


def extract_candidates_from_text(text):
    """Return list of (tier_idx, value, line_no, is_last_fallback) candidates."""
    lines = text.splitlines()
    candidates = []
    cutoff = False

    for i, raw in enumerate(lines):
        line = normalize_line(raw)
        up = line.upper()

        if any(k in up for k in SECTION_CUTOFFS):
            cutoff = True

        if cutoff:
            continue

        has_incl = ('INCL' in up) or ('INCLUSIVE' in up)
        is_excluded = False
        for ex in EXCLUSIONS:
            if ex in up:
                # If it's a GST/TAX exclusion but line says INCL/INCLUSIVE, override
                if has_incl and ex in ('TAX', 'GST', 'SST', 'TOTAL GST', 'TOTAL TAX', 'TOTAL SST', 'GST TOTAL', 'TAX TOTAL'):
                    continue
                is_excluded = True
                break
        if is_excluded:
            continue

        matched_tier = None
        for ti, keys in enumerate(TIERS):
            for k in keys:
                if k in up:
                    matched_tier = ti
                    break
            if matched_tier is not None:
                break

        if matched_tier is None:
            continue

        matches = AMOUNT_RE.findall(line)
        if matches:
            # take LAST
            try:
                val = to_float(matches[-1])
                candidates.append((matched_tier, val, i, False))
            except ValueError:
                pass
            continue

        # If line has no digits at all → look-ahead up to 2 non-empty non-excluded lines
        if not re.search(r'\d', line):
            for j in range(i + 1, min(i + 4, len(lines))):
                nxt_raw = lines[j]
                nxt = normalize_line(nxt_raw)
                nxt_up = nxt.upper()
                if not nxt.strip():
                    continue
                if any(k in nxt_up for k in SECTION_CUTOFFS):
                    break
                nxt_excl = False
                for ex in EXCLUSIONS:
                    if ex in nxt_up:
                        nxt_excl = True
                        break
                if nxt_excl:
                    continue
                nxt_matches = AMOUNT_RE.findall(nxt)
                if nxt_matches:
                    try:
                        val = to_float(nxt_matches[-1])
                        candidates.append((matched_tier, val, i, True))
                    except ValueError:
                        pass
                    break
        # else: has partial digits but no 2-decimal match → do not fall through
    return candidates


# ---------- Date extraction ----------

MONTHS = {m: i + 1 for i, m in enumerate(
    ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'])}

DATE_PATTERNS = [
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})'), 'dmy'),
    (re.compile(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})'), 'ymd'),
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)'), 'dmy2'),
    (re.compile(r'(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{2,4})'), 'dmony'),
]


def validate(y, mo, d):
    try:
        if not (2000 <= y <= 2099 and 1 <= mo <= 12 and 1 <= d <= 31):
            return None
        import datetime
        datetime.date(y, mo, d)
        return f"{y:04d}-{mo:02d}-{d:02d}"
    except Exception:
        return None


def try_swaps(y, mo, d):
    swaps = {'6': '0', '0': '6', '8': '3', '3': '8', '1': '7', '7': '1', '5': '6', '6': '5'}
    for field in ('mo', 'd'):
        v = mo if field == 'mo' else d
        s = str(v)
        for i, ch in enumerate(s):
            if ch in swaps:
                new = int(s[:i] + swaps[ch] + s[i + 1:])
                ny, nmo, nd = (y, new, d) if field == 'mo' else (y, mo, new)
                r = validate(ny, nmo, nd)
                if r:
                    return r
    return None


def parse_date_line(line):
    label_boost = any(k in line.upper() for k in ('DATE', 'TARIKH', 'INV'))
    for pat, kind in DATE_PATTERNS:
        for m in pat.finditer(line):
            if kind == 'ymd':
                y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            elif kind == 'dmy':
                a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if a > 12 and b <= 12:
                    d, mo = a, b
                else:
                    d, mo = a, b  # default dd/mm
            elif kind == 'dmy2':
                a, b, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
                y = 2000 + yy if yy <= 49 else 1900 + yy
                if a > 12 and b <= 12:
                    d, mo = a, b
                else:
                    d, mo = a, b
            elif kind == 'dmony':
                d = int(m.group(1))
                mo = MONTHS.get(m.group(2)[:3].upper(), 0)
                yy = int(m.group(3))
                y = yy if yy >= 100 else (2000 + yy if yy <= 49 else 1900 + yy)
            r = validate(y, mo, d) or try_swaps(y, mo, d)
            if r:
                return r, label_boost
    return None, False


def extract_date_from_texts(texts):
    boosted = []
    others = []
    for t in texts:
        for line in t.splitlines():
            r, boost = parse_date_line(line)
            if r:
                if boost:
                    boosted.append(r)
                else:
                    others.append(r)
    if boosted:
        return Counter(boosted).most_common(1)[0][0]
    if others:
        return Counter(others).most_common(1)[0][0]
    return None


def pick_total(all_candidates_per_variant):
    """Choose best amount across all variants."""
    # Flatten
    all_cands = []
    for cands in all_candidates_per_variant:
        all_cands.extend(cands)
    if not all_cands:
        return None

    # Lowest tier_idx wins first
    min_tier = min(c[0] for c in all_cands)
    tier_cands = [c for c in all_cands if c[0] == min_tier]

    # Count frequency across variants
    freq = Counter()
    last_line = {}
    for ti, val, ln, is_la in tier_cands:
        freq[round(val, 2)] += 1
        last_line[round(val, 2)] = max(last_line.get(round(val, 2), -1), ln)

    # Highest frequency; tie-break by latest line
    best = sorted(freq.keys(), key=lambda v: (-freq[v], -last_line[v]))
    return best[0]


def process_image(path):
    texts = []
    cands_per_var = []
    for im, cfg in variants(path):
        try:
            t = pytesseract.image_to_string(im, config=cfg)
        except Exception:
            t = ''
        texts.append(t)
        cands_per_var.append(extract_candidates_from_text(t))

    total = pick_total(cands_per_var)
    date = extract_date_from_texts(texts)
    return {
        'date': date,
        'total_amount': f"{total:.2f}" if total is not None else None,
    }


def main():
    files = sorted(glob.glob(os.path.join(IMG_DIR, '*.jpg')))
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    # Remove any other sheets
    for name in list(wb.sheetnames):
        if name != 'results':
            del wb[name]
    ws.append(['filename', 'date', 'total_amount'])

    for p in files:
        fn = os.path.basename(p)
        r = process_image(p)
        row_idx = ws.max_row + 1
        ws.cell(row=row_idx, column=1, value=fn)
        if r['date'] is None:
            ws.cell(row=row_idx, column=2, value=None)
        else:
            c = ws.cell(row=row_idx, column=2, value=str(r['date']))
            c.number_format = '@'
        if r['total_amount'] is None:
            ws.cell(row=row_idx, column=3, value=None)
        else:
            c = ws.cell(row=row_idx, column=3, value=str(r['total_amount']))
            c.number_format = '@'
        print(fn, r)

    wb.save(OUT)


if __name__ == '__main__':
    main()
