# ---------- Date extraction ----------

MONTHS = {m: i + 1 for i, m in enumerate(
    ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'])}

DATE_PATTERNS = [
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})'), 'dmy'),
    (re.compile(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})'), 'ymd'),
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)'), 'dmy2'),
    (re.compile(r'(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{2,4})'), 'dmony'),
]


def validate(y, mo, d):
    try:
        if not (2000 <= y <= 2099 and 1 <= mo <= 12 and 1 <= d <= 31):
            return None
        import datetime
        datetime.date(y, mo, d)
        return f"{y:04d}-{mo:02d}-{d:02d}"
    except Exception:
        return None


def try_swaps(y, mo, d):
    swaps = {'6': '0', '0': '6', '8': '3', '3': '8', '1': '7', '7': '1', '5': '6', '6': '5'}
    for field in ('mo', 'd'):
        v = mo if field == 'mo' else d
        s = str(v)
        for i, ch in enumerate(s):
            if ch in swaps:
                new = int(s[:i] + swaps[ch] + s[i + 1:])
                ny, nmo, nd = (y, new, d) if field == 'mo' else (y, mo, new)
                r = validate(ny, nmo, nd)
                if r:
                    return r
    return None


def parse_date_line(line):
    label_boost = any(k in line.upper() for k in ('DATE', 'TARIKH', 'INV'))
    for pat, kind in DATE_PATTERNS:
        for m in pat.finditer(line):
            if kind == 'ymd':
                y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            elif kind == 'dmy':
                a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if a > 12 and b <= 12:
                    d, mo = a, b
                else:
                    d, mo = a, b  # default dd/mm
            elif kind == 'dmy2':
                a, b, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
                y = 2000 + yy if yy <= 49 else 1900 + yy
                if a > 12 and b <= 12:
                    d, mo = a, b
                else:
                    d, mo = a, b
            elif kind == 'dmony':
                d = int(m.group(1))
                mo = MONTHS.get(m.group(2)[:3].upper(), 0)
                yy = int(m.group(3))
                y = yy if yy >= 100 else (2000 + yy if yy <= 49 else 1900 + yy)
            r = validate(y, mo, d) or try_swaps(y, mo, d)
            if r:
                return r, label_boost
    return None, False


def extract_date_from_texts(texts):
    boosted = []
    others = []
    for t in texts:
        for line in t.splitlines():
            r, boost = parse_date_line(line)
            if r:
                if boost:
                    boosted.append(r)
                else:
                    others.append(r)
    if boosted:
        return Counter(boosted).most_common(1)[0][0]
    if others:
        return Counter(others).most_common(1)[0][0]
    return None


def pick_total(all_candidates_per_variant):
    """Choose best amount across all variants."""
    # Flatten
    all_cands = []
    for cands in all_candidates_per_variant:
        all_cands.extend(cands)
    if not all_cands:
        return None

    # Lowest tier_idx wins first
    min_tier = min(c[0] for c in all_cands)
    tier_cands = [c for c in all_cands if c[0] == min_tier]

