    for ti, val, ln, is_la in tier_cands:
        freq[round(val, 2)] += 1
        last_line[round(val, 2)] = max(last_line.get(round(val, 2), -1), ln)

    # Highest frequency; tie-break by latest line
    best = sorted(freq.keys(), key=lambda v: (-freq[v], -last_line[v]))
    return best[0]


def process_image(path):
    texts = []
    cands_per_var = []
    for im, cfg in variants(path):
        try:
            t = pytesseract.image_to_string(im, config=cfg)
        except Exception:
