                    d, mo = a, b  # default dd/mm
            elif kind == 'dmy2':
                a, b, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
                y = 2000 + yy if yy <= 49 else 1900 + yy
                if a > 12 and b <= 12:
                    d, mo = a, b
                else:
                    d, mo = a, b
            elif kind == 'dmony':
                d = int(m.group(1))
                mo = MONTHS.get(m.group(2)[:3].upper(), 0)
                yy = int(m.group(3))
                y = yy if yy >= 100 else (2000 + yy if yy <= 49 else 1900 + yy)
            r = validate(y, mo, d) or try_swaps(y, mo, d)
            if r:
                return r, label_boost
    return None, False


def extract_date_from_texts(texts):
    boosted = []
    others = []
    for t in texts:
        for line in t.splitlines():
            r, boost = parse_date_line(line)
            if r:
                if boost:
                    boosted.append(r)
                else:
                    others.append(r)
    if boosted:
        return Counter(boosted).most_common(1)[0][0]
    if others:
        return Counter(others).most_common(1)[0][0]
    return None


def pick_total(all_candidates_per_variant):
    """Choose best amount across all variants."""
    # Flatten
    all_cands = []
    for cands in all_candidates_per_variant:
        all_cands.extend(cands)
    if not all_cands:
        return None

    # Lowest tier_idx wins first
    min_tier = min(c[0] for c in all_cands)
    tier_cands = [c for c in all_cands if c[0] == min_tier]

    # Count frequency across variants
    freq = Counter()
    last_line = {}
    for ti, val, ln, is_la in tier_cands:
        freq[round(val, 2)] += 1
        last_line[round(val, 2)] = max(last_line.get(round(val, 2), -1), ln)

    # Highest frequency; tie-break by latest line
    best = sorted(freq.keys(), key=lambda v: (-freq[v], -last_line[v]))
    return best[0]


def process_image(path):
    texts = []
    cands_per_var = []
    for im, cfg in variants(path):
        try:
            t = pytesseract.image_to_string(im, config=cfg)
        except Exception:
            t = ''
        texts.append(t)
        cands_per_var.append(extract_candidates_from_text(t))

    total = pick_total(cands_per_var)
    date = extract_date_from_texts(texts)
    return {
        'date': date,
        'total_amount': f"{total:.2f}" if total is not None else None,
    }


def main():
    files = sorted(glob.glob(os.path.join(IMG_DIR, '*.jpg')))
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    # Remove any other sheets
    for name in list(wb.sheetnames):
        if name != 'results':
            del wb[name]
    ws.append(['filename', 'date', 'total_amount'])

    for p in files:
        fn = os.path.basename(p)
        r = process_image(p)
        row_idx = ws.max_row + 1
        ws.cell(row=row_idx, column=1, value=fn)
        if r['date'] is None:
            ws.cell(row=row_idx, column=2, value=None)
        else:
            c = ws.cell(row=row_idx, column=2, value=str(r['date']))
            c.number_format = '@'
        if r['total_amount'] is None:
            ws.cell(row=row_idx, column=3, value=None)
        else:
            c = ws.cell(row=row_idx, column=3, value=str(r['total_amount']))
            c.number_format = '@'
        print(fn, r)

    wb.save(OUT)


if __name__ == '__main__':
    main()
